(()=>{
const studioPhoto="data:image/jpeg;base64,";
const targets={content:['Including the workshop’s time and room.','Including a photo used as a modeling reference.'],structure:['Putting links to Workshops and Visit Us in a menu.','Grouping each workshop’s information in its own box.'],style:['Making the page heading dark green.','Using a purple background and white text for the reservation button.'],accessibility:['Image text alternative (alt text)']};
const candidates=['Event details','Workshop information','Navigation menu','Workshop grouping','Heading appearance','Button appearance','Image text alternative (alt text)'];
const options={content:['Teaser only','Full workshop details'],structure:['One long stream','Grouped sections'],size:['Compact','Comfortable','Large'],style:['Quiet','Bold'],alt:['No image description','Meaningful image description']};
const defaults={content:'Teaser only',structure:'One long stream',size:'Compact',style:'Bold',alt:'No image description'};
let ctx;
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function site(settings=defaults,learning=false){const full=learning||settings.content==='Full workshop details',group=learning||settings.structure==='Grouped sections',alt=learning||settings.alt==='Meaningful image description',size=learning?'Comfortable':settings.size,bold=learning||settings.style==='Bold';return `<!doctype html><html lang="en"><head><meta charset="utf-8"><style>*{box-sizing:border-box}body{margin:0;background:#fffdf5;color:#20342e;font-family:Arial,sans-serif;font-size:${size==='Large'?24:size==='Compact'?12:17}px;line-height:1.55}header{background:${bold?'#ffd252':'#e7eee9'};padding:24px}h1{font-size:2em;line-height:1.1;color:#183c31;margin:6px 0}nav{display:flex;gap:18px;flex-wrap:wrap;background:#173e32;padding:12px 24px}nav a{color:white}main{padding:24px}.workshops{display:${group?'grid':'block'};grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:18px}.card{border:${group?'2px solid #bccdc3':'0'};padding:${group?'18px':'4px'};margin-bottom:12px;background:${bold?'#fff2c7':'#f4f6f3'}}h2,h3{line-height:1.2}a{color:#174e40}a:focus-visible,button:focus-visible{outline:4px solid #bc1680;outline-offset:4px}button,.reserve{display:inline-block;border:0;border-radius:6px;padding:12px 18px;background:${bold?'#6237ab':'#274d41'};color:white;font:inherit;font-weight:bold}.art{font-size:45px;display:block;background:#dcebe5;padding:12px}footer{padding:20px;background:#e7eee9}small{font-size:.85em}</style></head><body><header><p>AFTER-SCHOOL STUDIO</p><h1>Make something after school</h1><p>Free workshops for students. Beginners welcome.</p></header><nav aria-label="Studio sections"><a href="#workshops">Workshops</a><a href="#visit">Visit us</a><a href="#reserve">Reserve a place</a></nav><main><h2 id="workshops">Workshops</h2><div class="workshops"><section class="card"><figure style="margin:0"><img class="art" src="${studioPhoto}" ${alt?'alt="A tan Chihuahua with upright ears and its tongue out, resting on a gray blanket"':''} style="width:100%;height:190px;object-fit:cover;padding:0"><figcaption style="font-size:.85em">Modeling reference: our workshop mascot</figcaption></figure><h3>3D Modeling Lab</h3><p>${full?'Learn to build a 3D model using the dog photo as a reference. Monday, 3:15–4:15 p.m. in Room 238. Materials provided.':'Build a 3D model with us. Ask around for details!'}</p></section><section class="card"><h3>Game Design</h3><p>${full?'Create a game using school computers. Wednesday, 3:15–4:15 p.m. in Room 238. No experience needed.':'Make a game. More information soon.'}</p></section></div><section id="visit"><h2>Visit us</h2><p>${full?'Meet in the computer science room after dismissal. No experience needed. Ask Mr. Pino in Room 238 about access needs.':'Come after school. We will see you there.'}</p></section><section id="reserve"><h2>Reserve a place</h2><p>Tell Mr. Pino which workshop you want to join.</p><a class="reserve" href="#reservation-note">How to reserve</a><p id="reservation-note">Ask Mr. Pino in Room 238 to reserve your place.</p></section></main><footer>After-School Studio</footer></body></html>`}
function browser(id,title){return `<div class="fake-browser"><div class="browser-bar"><span aria-hidden="true">● ● ●</span> <span>${title}</span></div><iframe id="${id}" title="${title}" sandbox="allow-same-origin"></iframe></div>`}
function readabilitySnippet(improved=false){return `<!doctype html><html lang="en"><meta charset="utf-8"><style>body{margin:0;padding:24px;background:#fff;font-family:Arial,sans-serif}.notice{padding:24px;background:#f5f5f5;border:1px solid #ddd;color:${improved?'#202b32':'#b5b5b5'};font-size:${improved?'20':'11'}px;line-height:1.6}h2{font-size:1.5em;margin-top:0}</style><div class="notice"><h2>Game Design</h2><p>Create a game using school computers.</p><p>Wednesday, 3:15–4:15 p.m.<br>Computer science room, Room 238.</p><p>Ask Mr. Pino to reserve a place.</p></div></html>`}
function design(state){return {...defaults,...state.mondayDesign}}
window.PurposeLab={render(p,c){ctx=c;if(p.id==='design')return `<div class="cssa-overview">${[['C','Content','What’s on it','Media and information.'],['S','Structure','How it’s organized','Headings, sections, and navigation.'],['S','Style','How it looks','Colors, fonts, sizes, and spacing.'],['A','Accessibility','Who can use it','Make the site usable for everyone.']].map(([letter,name,meaning,examples])=>`<section class="cssa-card"><span class="cssa-letter" aria-hidden="true">${letter}</span><h3>${name}</h3><strong>${meaning}</strong><p>${examples}</p></section>`).join('')}</div><section class="block observe"><strong>Today</strong><p>Learn what each component contributes. Then design a page where they work together.</p></section>`;if(p.kind==='component')return c.block('observe',p.id==='accessibility'?'COMPARE · 2 MINUTES':'IDENTIFY · 2 MINUTES',`${p.id==='accessibility'?'<p>Compare the two 3D Modeling Lab boxes. One shows the photo; the other shows its alt text when the photo does not load.</p>':`<p>Find <strong>two examples of ${p.name[0]}</strong> in this website. Inspect the page, then select the two features below. You are identifying features, not changing the site.</p>`}${p.id==='accessibility'?'<div class="access-compare"><section><h3>Image loaded</h3>'+browser('example-site','studio.example / image loaded')+'</section><section><h3>Image not loaded</h3>'+browser('alt-example-site','studio.example / image not loaded')+'</section></div>':browser('example-site','studio.example / workshops')}${p.id==='accessibility'?'':`<fieldset class="feature-picks"><legend>${({content:'Which TWO choices provide information or media for the visitor?',structure:'Which TWO choices organize the page or help visitors find things?',style:'Which TWO choices change how the page looks?'}[p.id]||'Choose two examples.')}</legend>${({content:['Including the workshop’s time and room.','Making the page heading dark green.','Including a photo used as a modeling reference.','Putting workshop information in separate boxes.'],structure:['Putting links to Workshops and Visit Us in a menu.','Grouping each workshop’s information in its own box.','Making the page heading dark green.','Including a photo of a dog.'],style:['Putting links to Workshops and Visit Us in a menu.','Making the page heading dark green.','Including the workshop’s time and room.','Using a purple background and white text for the reservation button.']}[p.id]||candidates).map((v,i)=>`<label><input type="checkbox" data-pick="${v}" ${(c.state.mondayPicks?.[p.id]||[]).includes(v)?'checked':''}> ${v}</label>`).join('')}</fieldset><button class="secondary" id="check-picks">Check my examples</button><p id="pick-feedback" role="status"></p>`}${p.id==='accessibility'?'<div class="access-help"><p><strong>Compare:</strong> What can a visitor learn about the image when the photo does not load?</p></div><h3>Another example: readable text</h3><p>This Game Design announcement has the same information in both versions. Switch between them and notice what changes.</p><div class="compare-actions"><button class="secondary" id="read-original" aria-pressed="true">Original</button><button class="secondary" id="read-improved" aria-pressed="false">Improved</button><strong id="read-status" role="status">Original: small, low-contrast text</strong></div>'+browser('readability-site','studio.example / game design')+'':''}`);
if(p.kind==='redesign')return c.block('try','REDESIGN STUDIO',`<div class="design-options">${Object.entries(options).map(([key,values])=>`<label>${{content:'Content',structure:'Structure',size:'Text size',style:'Visual treatment',alt:'Image access'}[key]}<select data-design="${key}">${values.map(v=>`<option ${design(c.state)[key]===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}</div><p class="caption">Try different combinations. Check what happens to information, wrapping, emphasis, and access. Your selections save with your work.</p><div class="compare-actions"><button class="secondary" id="compare-original" aria-pressed="false">Show original</button><button class="secondary" id="reset-design">Reset my design</button><strong id="design-view" role="status">Your design</strong></div>${browser('design-site','studio.example / your design')}<p id="design-summary" class="caption"></p>`);return ''},
bind(p,c){ctx=c;if(c.state.mondayPicks){for(const key of Object.keys(c.state.mondayPicks))c.state.mondayPicks[key]=c.state.mondayPicks[key].map(v=>v==='Drawing description'?'Workshop information':v==='Image description'?'Image text alternative (alt text)':v==='Navigation menu'?'Putting links to Workshops and Visit Us in a menu.':v==='Workshop grouping'?'Grouping each workshop’s information in its own box.':v==='Event details'?'Including the workshop’s time and room.':v==='Workshop information'?'Including a photo used as a modeling reference.':v==='Heading appearance'?'Making the page heading dark green.':v==='Button appearance'?'Using a purple background and white text for the reservation button.':v);}if(p.kind==='component'){document.querySelector('#example-site').srcdoc=site(defaults,true);if(p.id==='accessibility'){const full=site(defaults,true);const card=full.match(/<section class="card">[\s\S]*?<\/section>/)[0];const loaded=full.replace(/<body>[\s\S]*<\/body>/,'<body><main>'+card+'</main></body>');document.querySelector('#example-site').srcdoc=loaded;const image=loaded.match(/<img class="art"[^>]*>/)[0];const fallback='<div role="img" aria-label="A tan Chihuahua with upright ears and its tongue out, resting on a gray blanket" style="min-height:190px;padding:18px;border:1px solid #8a9991;background:#f2f3ef;display:flex;align-items:center">A tan Chihuahua with upright ears and its tongue out, resting on a gray blanket.</div>';document.querySelector('#alt-example-site').srcdoc=loaded.replace(image,fallback);}document.querySelectorAll('[data-pick]').forEach(el=>el.onchange=()=>{c.state.mondayPicks??={};c.state.mondayPicks[p.id]=[...document.querySelectorAll('[data-pick]:checked')].map(x=>x.dataset.pick);c.state.answers[p.id+'-identified']=c.state.mondayPicks[p.id].join('; ');c.persist();document.querySelector('#pick-feedback').textContent='';});if(p.id==='accessibility'){const showReadability=improved=>{document.querySelector('#readability-site').srcdoc=readabilitySnippet(improved);document.querySelector('#read-original').setAttribute('aria-pressed',String(!improved));document.querySelector('#read-improved').setAttribute('aria-pressed',String(improved));document.querySelector('#read-status').textContent=improved?'Improved: larger, higher-contrast text':'Original: small, low-contrast text';};document.querySelector('#read-original').onclick=()=>showReadability(false);document.querySelector('#read-improved').onclick=()=>showReadability(true);showReadability(false);}if(document.querySelector('#check-picks'))document.querySelector('#check-picks').onclick=()=>{const selected=c.state.mondayPicks?.[p.id]||[],correct=targets[p.id];document.querySelector('#pick-feedback').textContent=selected.length!==2?'Choose two examples, then check again.':correct.every(x=>selected.includes(x))?'These examples show '+p.name[0]+'. Now explain what one does for a visitor.':p.id==='structure'?'Reconsider your pair. Focus on how information is arranged or how a visitor moves through the page.':'Look again at the definition. Focus on what the selected features do on the page.';};}
if(p.kind==='redesign'){c.state.fix=design(c.state);c.state.answers['saved-design-settings']=JSON.stringify(c.state.fix);let original=false;const update=()=>{const d=design(c.state);document.querySelector('#design-site').srcdoc=site(original?defaults:d);document.querySelector('#design-view').textContent=original?'Original page':'Your design';document.querySelector('#compare-original').textContent=original?'Return to my design':'Show original';document.querySelector('#compare-original').setAttribute('aria-pressed',String(original));document.querySelector('#design-summary').textContent=Object.entries(d).map(([k,v])=>k+': '+v).join(' · ');};document.querySelectorAll('[data-design]').forEach(el=>el.onchange=()=>{c.state.mondayDesign=design(c.state);c.state.mondayDesign[el.dataset.design]=el.value;c.state.answers['saved-design-settings']=JSON.stringify(c.state.mondayDesign);c.state.fix=c.state.mondayDesign;original=false;c.persist();update();});document.querySelector('#compare-original').onclick=()=>{original=!original;update()};document.querySelector('#reset-design').onclick=()=>{c.state.mondayDesign={...defaults};c.state.fix=c.state.mondayDesign;c.state.answers['saved-design-settings']=JSON.stringify(c.state.mondayDesign);document.querySelectorAll('[data-design]').forEach(el=>el.value=defaults[el.dataset.design]);original=false;c.persist();update()};update();}},
exportLines({state}){return ['IDENTIFIED FEATURES',...Object.entries(state.mondayPicks||{}).map(([k,v])=>k+': '+v.join('; ')),'FINAL DESIGN',...Object.entries(design(state)).map(([k,v])=>k+': '+v)]},
printEvidence({state,esc,blank}){return blank?'':`<section><h2>Identified features and design settings</h2><pre style="white-space:pre-wrap">${esc(this.exportLines({state}).join('\n'))}</pre></section>`;}}
})();



